    let file = File::open(corpus)?;
    let data = unsafe { Mmap::map(&file)? };
    let data: &[u8] = &data;
    let target = (16usize << 20).max(data.len() / 512);
    let mut chunks: Vec<&[u8]> = Vec::new();
    let mut start = 0;
    while start < data.len() {
        let mut end = (start + target).min(data.len());
        if end < data.len() {
            end = match memchr_nl(&data[end..]) {
                Some(i) => end + i + 1,
                None => data.len(),
            };
        }
        chunks.push(&data[start..end]);
        start = end;
    }
    let results: Vec<ChunkResult> = chunks
        .par_iter()
        .enumerate()
        .map(|(c, ch)| process_chunk(c, ch, dir))
        .collect::<std::io::Result<_>>()?;

    let mut bases = Vec::with_capacity(results.len());
    let mut n: u32 = 0;
    for r in &results {
        bases.push(n);
        n += r.ids.len() as u32;
    }

