        .map(|c| unsafe { Mmap::map(&File::open(seg_path(dir, c))?) })
        .collect::<std::io::Result<_>>()?;
    let merge = || -> std::io::Result<()> {
        (0..NPART).into_par_iter().try_for_each(|p| merge_partition(p, &segs, &bases, dir))
    };

