        let mut total_tokens: u64 = 0;
        let mut ids = BufWriter::new(File::create(dir.join("ids.bin"))?);
        let mut dls = BufWriter::new(File::create(dir.join("dl.bin"))?);
        let mut docs = BufWriter::new(File::create(dir.join("docs.bin"))?);
