                dls.write_all(&r.dls[i].to_le_bytes())?;
                total_tokens += r.dls[i] as u64;
                docs.write_all(&(c as u32).to_le_bytes())?;
                for v in r.recs[i] {
                    docs.write_all(&v.to_le_bytes())?;
                }
                idmap.push((r.ids[i], bases[c] + i as u32));
            }
