    }

    /// Returns (title, text) for an external id.
    pub fn doc(&self, id: u32) -> Option<(&str, String)> {
        let m: &[u8] = &self.idmap;
        let n = m.len() / 8;
        let (mut lo, mut hi) = (0, n);
        while lo < hi {
            let mid = (lo + hi) / 2;
            let v = u32_at(m, mid * 8);
            match v.cmp(&id) {
                Ordering::Less => lo = mid + 1,
                Ordering::Greater => hi = mid,
                Ordering::Equal => {
