                    let off = u32_at(&self.docs, r + 4) as usize;
                    let tl = u32_at(&self.docs, r + 8) as usize;
                    let xl = u32_at(&self.docs, r + 12) as usize;
                    let cl = u32_at(&self.docs, r + 16) as usize;
                    let st = &self.stores[c];
                    let text = zstd::bulk::decompress(&st[off + tl..off + tl + cl], xl).ok()?;
                    let text = String::from_utf8(text).ok()?;
                    return Some((self.title(ord), text));
                }
            }
        }
        None
    }

    fn cursor(&self, t: &TermInfo) -> Cursor<'_> {
        let p: &[u8] = &self.posts[t.part];
        let nblocks = (t.df as usize).div_ceil(BLOCK);
        let off = t.off as usize;
        let skips = &p[off..off + nblocks * 12];
        let docs = &p[off + nblocks * 12..off + nblocks * 12 + t.doc_bytes as usize];
        let pos = &p[off + nblocks * 12 + t.doc_bytes as usize..];
        let mut c = Cursor {
            skips,
            docs,
            pos,
            df: t.df,
            nblocks,
            block: usize::MAX,
            bdocs: [0; BLOCK],
            btfs: [0; BLOCK],
            bpos: [0; BLOCK],
            bn: 0,
            i: 0,
            pos_ready: false,
            cur: 0,
        };
        c.load_block(0);
        c
    }
}

pub const END: u32 = u32::MAX;

struct Cursor<'a> {
    skips: &'a [u8],
    docs: &'a [u8],
    pos: &'a [u8],
    df: u32,
    nblocks: usize,
    block: usize,
    bdocs: [u32; BLOCK],
    btfs: [u32; BLOCK],
    bpos: [u32; BLOCK],
    bn: usize,
    i: usize,
    pos_ready: bool,
    cur: u32,
}

impl<'a> Cursor<'a> {
    #[inline]
    fn last_of(&self, b: usize) -> u32 {
        u32_at(self.skips, b * 12 + 8)
    }

    fn load_block(&mut self, b: usize) {
        if b >= self.nblocks {
            self.cur = END;
            self.block = b;
            return;
        }
        self.block = b;
        let mut p = u32_at(self.skips, b * 12) as usize;
        let n = if b + 1 == self.nblocks { self.df as usize - b * BLOCK } else { BLOCK };
        let mut prev = if b == 0 { 0 } else { self.last_of(b - 1) };
        for j in 0..n {
            prev += get_varint(self.docs, &mut p);
            self.bdocs[j] = prev;
            self.btfs[j] = get_varint(self.docs, &mut p);
        }
        self.bn = n;
        self.i = 0;
        self.pos_ready = false;
        self.cur = self.bdocs[0];
    }

    #[inline]
    fn doc(&self) -> u32 {
        self.cur
    }

    #[inline]
    fn next(&mut self) {
        self.i += 1;
        if self.i < self.bn {
            self.cur = self.bdocs[self.i];
        } else {
            self.load_block(self.block + 1);
        }
    }

    /// Advance to the first doc >= target.
    fn advance(&mut self, target: u32) {
        if self.cur >= target {
            return;
        }
        if self.last_of(self.block) < target {
            // binary search for the first block with last >= target
            let (mut lo, mut hi) = (self.block + 1, self.nblocks);
            while lo < hi {
                let mid = (lo + hi) / 2;
                if self.last_of(mid) < target {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            self.load_block(lo);
            if self.cur == END {
                return;
            }
        }
        while self.bdocs[self.i] < target {
            self.i += 1;
        }
        self.cur = self.bdocs[self.i];
    }

    #[inline]
    fn tf(&self) -> u32 {
        self.btfs[self.i]
    }

    fn positions(&mut self, out: &mut Vec<u32>) {
        if !self.pos_ready {
            let mut p = u32_at(self.skips, self.block * 12 + 4) as usize;
            for j in 0..self.bn {
                self.bpos[j] = p as u32;
                skip_varints(self.pos, &mut p, self.btfs[j]);
            }
            self.pos_ready = true;
        }
        out.clear();
        let mut p = self.bpos[self.i] as usize;
        let mut v = 0;
        for _ in 0..self.btfs[self.i] {
            v += get_varint(self.pos, &mut p);
            out.push(v);
        }
    }
}

struct Clause {
    neg: bool,
    tokens: Vec<Vec<u8>>,
}

fn parse_query(q: &str) -> Vec<Clause> {
    let chars: Vec<char> = q.chars().collect();
    let mut i = 0;
    let mut out = Vec::new();
    loop {
        while i < chars.len() && chars[i].is_whitespace() {
            i += 1;
        }
        if i >= chars.len() {
            break;
        }
        let mut neg = false;
        if chars[i] == '-' {
            neg = true;
            i += 1;
        }
        let start;
        let end;
        if i < chars.len() && chars[i] == '"' {
            i += 1;
            start = i;
            while i < chars.len() && chars[i] != '"' {
                i += 1;
            }
            end = i;
            if i < chars.len() {
                i += 1;
            }
        } else {
            start = i;
            while i < chars.len() && !chars[i].is_whitespace() {
                i += 1;
            }
            end = i;
        }
        let s: String = chars[start..end].iter().collect();
        let tokens = tokens(&s);
        if !tokens.is_empty() {
            out.push(Clause { neg, tokens });
        }
    }
    out
}

#[derive(Clone, Copy)]
pub struct Hit {
    pub score: f64,
    pub id: u32,
    pub ord: u32,
}

// "Greater" = worse, so a BinaryHeap keeps the worst hit on top.
impl PartialEq for Hit {
    fn eq(&self, o: &Self) -> bool {
        self.cmp(o) == Ordering::Equal
    }
}
impl Eq for Hit {}
impl PartialOrd for Hit {
    fn partial_cmp(&self, o: &Self) -> Option<Ordering> {
        Some(self.cmp(o))
    }
}
impl Ord for Hit {
    fn cmp(&self, o: &Self) -> Ordering {
        o.score.total_cmp(&self.score).then(self.id.cmp(&o.id))
    }
}

struct CClause {
    terms: Vec<usize>, // indices into cursors
}

fn phrase_match(cl: &CClause, curs: &mut [Cursor], bufs: &mut Vec<Vec<u32>>) -> bool {
    let m = cl.terms.len();
    while bufs.len() < m {
        bufs.push(Vec::new());
    }
    for (j, &t) in cl.terms.iter().enumerate() {
        curs[t].positions(&mut bufs[j]);
    }
    let mut ptrs = vec![0usize; m];
    'outer: for &p0 in bufs[0].iter() {
        for j in 1..m {
            let want = p0 + j as u32;
            let b = &bufs[j];
            let mut k = ptrs[j];
            while k < b.len() && b[k] < want {
                k += 1;
            }
            ptrs[j] = k;
            if k >= b.len() {
                return false;
            }
            if b[k] != want {
                continue 'outer;
            }
        }
        return true;
    }
    false
}

impl Index {
    pub fn search(&self, q: &str, k: usize) -> (u64, Vec<Hit>) {
        let clauses = parse_query(q);
        if !clauses.iter().any(|c| !c.neg) {
            return (0, Vec::new());
        }
        let mut terms: Vec<Vec<u8>> = Vec::new();
        let mut infos: Vec<Option<TermInfo>> = Vec::new();
        let mut tid = |t: &Vec<u8>, terms: &mut Vec<Vec<u8>>, infos: &mut Vec<Option<TermInfo>>| -> usize {
            if let Some(i) = terms.iter().position(|x| x == t) {
                return i;
            }
            terms.push(t.clone());
            infos.push(self.lookup(t));
            terms.len() - 1
        };
        let mut pos_clauses = Vec::new();
        let mut neg_clauses = Vec::new();
        let mut positive_terms: Vec<usize> = Vec::new();
        for c in &clauses {
            let ts: Vec<usize> = c.tokens.iter().map(|t| tid(t, &mut terms, &mut infos)).collect();
            if c.neg {
                if ts.iter().all(|&t| infos[t].is_some()) {
                    neg_clauses.push(CClause { terms: ts });
                }
            } else {
                if ts.iter().any(|&t| infos[t].is_none()) {
                    return (0, Vec::new());
                }
                for &t in &ts {
                    if !positive_terms.contains(&t) {
                        positive_terms.push(t);
                    }
                }
                if ts.len() > 1 {
                    pos_clauses.push(CClause { terms: ts });
                }
            }
        }
        // cursors only for terms actually needed
        let mut curs: Vec<Cursor> = Vec::new();
        let mut cmap = vec![usize::MAX; terms.len()];
        for (t, info) in infos.iter().enumerate() {
            let used = positive_terms.contains(&t) || neg_clauses.iter().any(|c| c.terms.contains(&t));
            if used {
                cmap[t] = curs.len();
                curs.push(self.cursor(info.as_ref().unwrap()));
            }
        }
        for c in pos_clauses.iter_mut().chain(neg_clauses.iter_mut()) {
            for t in c.terms.iter_mut() {
                *t = cmap[*t];
            }
        }
        let n = self.n as f64;
        let mut pt: Vec<(usize, f64)> = positive_terms
            .iter()
            .map(|&t| {
                let df = infos[t].unwrap().df as f64;
                (cmap[t], (1.0 + (n - df + 0.5) / (df + 0.5)).ln())
            })
            .collect();
        // Fixed summation order (by token) for deterministic scores; iteration order by df.
        let score_terms = pt.clone();
        pt.sort_by_key(|&(c, _)| curs[c].df);
        let order: Vec<usize> = pt.iter().map(|&(c, _)| c).collect();

        let mut heap: BinaryHeap<Hit> = BinaryHeap::with_capacity(k + 1);
        let mut total: u64 = 0;
        let mut bufs: Vec<Vec<u32>> = Vec::new();
        let lead = order[0];
        let dl: &[u8] = &self.dl;
        let avgdl = self.avgdl;
        loop {
            let mut target = curs[lead].doc();
            if target == END {
                break;
            }
            // leapfrog until all positive cursors agree
            let mut agreed = false;
            'lf: loop {
                for &c in &order {
                    curs[c].advance(target);
                    let d = curs[c].doc();
                    if d == END {
                        break 'lf;
                    }
                    if d > target {
                        target = d;
                        continue 'lf;
                    }
                }
                agreed = true;
                break;
            }
            if !agreed {
                break;
            }
            let d = target;
            let mut ok = pos_clauses.iter().all(|c| phrase_match(c, &mut curs, &mut bufs));
            if ok {
                for c in &neg_clauses {
                    let mut all = true;
                    for &t in &c.terms {
                        curs[t].advance(d);
                        if curs[t].doc() != d {
                            all = false;
                            break;
                        }
                    }
                    if all && (c.terms.len() == 1 || phrase_match(c, &mut curs, &mut bufs)) {
                        ok = false;
                        break;
                    }
                }
            }
            if ok {
                total += 1;
                let norm = K1 * (1.0 - B + B * u32_at(dl, d as usize * 4) as f64 / avgdl);
                let mut score = 0.0;
                for &(c, idf) in &score_terms {
                    let tf = curs[c].tf() as f64;
                    score += idf * tf * (K1 + 1.0) / (tf + norm);
                }
                let h = Hit { score, id: self.ext_id(d), ord: d };
                if heap.len() < k {
                    heap.push(h);
                } else if h < *heap.peek().unwrap() {
                    *heap.peek_mut().unwrap() = h;
                }
            }
            curs[lead].next();
        }
        let mut hits = heap.into_vec();
        hits.sort();
        (total, hits)
    }
}

