+                    if d == END {
+                        break 'lf;
+                    }
+                    if d > target {
+                        target = d;
+                        continue 'lf;
+                    }
+                }
+                agreed = true;
+                break;
+            }
+            if !agreed {
+                break;
+            }
+            let d = target;
+            let mut ok = pos_clauses.iter().all(|c| phrase_match(c, &mut curs, &mut bufs));
+            if ok {
+                for c in &neg_clauses {
+                    let mut all = true;
+                    for &t in &c.terms {
+                        curs[t].advance(d);
+                        if curs[t].doc() != d {
+                            all = false;
+                            break;
+                        }
+                    }
+                    if all && (c.terms.len() == 1 || phrase_match(c, &mut curs, &mut bufs)) {
